cat <<'EOF' > /tmp/t.ts
import {indexSitesFixesConfig} from './src/generators/utils/parse';
const text = `====

thisisnotarealwebsite.dummy

CSS
.Not-A-Real-Selector {
    not-a-real-CSS-property: url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAMAAAACCAIAAAASFvFNAAAAFklEQVQImWO84ePDwMCQ8uEDEwMMAAA1TAO4kytpLAAAAABJRU5ErkJggg==') !important;
}

IGNORE INLINE STYLE
.test
`;
const idx = indexSitesFixesConfig(text);
console.log(JSON.stringify(idx.domainPatterns));
console.log(JSON.stringify(idx.domains));
EOF
npx ts-node -T /tmp/t.ts 2>&1 | tail -30

mkdir -p tests/tmp_scratch && cat <<'EOF' > tests/tmp_scratch/scratch.tests.ts
import {indexSitesFixesConfig} from '../../src/generators/utils/parse';

test('base64 padding does not break parsing', () => {
    const text = `====

thisisnotarealwebsite.dummy

CSS
.Not-A-Real-Selector {
    not-a-real-CSS-property: url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAMAAAACCAIAAAASFvFNAAAAFklEQVQImWO84ePDwMCQ8uEDEwMMAAA1TAO4kytpLAAAAABJRU5ErkJggg==') !important;
}

IGNORE INLINE STYLE
.test
`;
    const idx = indexSitesFixesConfig(text);
    expect(Object.keys(idx.domainPatterns)).not.toContain(`') !important;`);
    expect(idx.domains['thisisnotarealwebsite.dummy']).toBeDefined();
});
EOF
npx jest --config=tests/jest.config.js tests/tmp_scratch/scratch.tests.ts 2>&1 | tail -30
rm -rf tests/tmp_scratch

